/* ----------------------------------------------------------------
     [ Start Products ]
-----------------------------------------------------------------*/
.products .section-head {
  margin-bottom: 40px; }

.products .section-head p {
  margin: 15px 0; }

.products .item {
  margin-bottom: 15px;
  overflow: hidden;
  position: relative;
  text-align: center; }

.products .item:hover .info {
  bottom: 30%; }

.products .item:hover .info .icon {
  display: inline-block;
  margin-top: 38px; }

.products .item:hover .product-img:after {
  height: 100%;
  opacity: .6;
  top: 0;
  visibility: visible; }

.products .item .product-img {
  overflow: hidden;
  position: relative; }

.products .item .product-img:after {
  background-color: rgba(0, 0, 0, 0.9);
  border-top: 2px solid #ce9e51;
  content: '';
  height: 25%;
  left: 0;
  opacity: 1;
  position: absolute;
  top: 75%;
  transition: all .4s;
  visibility: visible;
  width: 100%; }

.products .item .info {
  color: #fff;
  bottom: 5%;
  left: 0;
  padding: 0 15px;
  position: absolute;
  transition: all .4s;
  width: 100%;
  z-index: 4; }

.products .item .info h6, .products .item .info h6 a {
  font-size: 16px;
  letter-spacing: 1px;
  margin-bottom: 5px;
  color: #fff; }

.products .item .info span {
  font-size: 13px;
  font-style: italic;
  margin-bottom: 10px;
  color: #eee; }

.products .item .info .icon {
  color: #eee;
  cursor: pointer;
  display: none;
  font-size: 16px;
  margin: 7px 10px;
